-- Упражнения книги 19, глава 12 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'virt-sim-net-nat', 0, 'lab', 'Доска сети: сеть контейнера своими руками, NAT', 'Повторите то, что делает Docker для контейнера: пространство имён, пара veth, мост с адресом шлюза, маршрут по умолчанию в контейнере, пересылка пакетов в хосте и правило masquerade. Доска трассирует пинг шаг за шагом и показывает, где он обрывается. Пять сценариев: собрать сеть с нуля, найти недостающее правило masquerade, найти выключенную пересылку (ip_forward), найти отсутствующий маршрут по умолчанию и опубликовать порт контейнера правилом DNAT. Упражнение решено, когда решены все сценарии.', '', 'Пакет для другой сети уходит на шлюз; шлюз должен пересылать пакеты и иметь ногу в сети назначения. Внешняя сеть не знает частных адресов: без masquerade ответ не вернётся. Опубликовать порт можно только правилом DNAT, которое указывает на хост внутри.', '{}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'la12-netns-state', 1, 'func', 'Что построил скрипт', 'Скрипт — текст команд оболочки, которыми собирают сеть из пространств, кабелей veth и мостов. Обрабатывайте строки по порядку. Пустые строки и строки, начинающиеся с #, пропускайте; строка, оканчивающаяся обратной косой чертой, продолжается на следующей (склейте их через пробел). Префикс sudo отбросьте. Команда выполняется в пространстве host, если перед ней нет префикса ip netns exec ИМЯ или ключа ip -n ИМЯ; с префиксом — в пространстве ИМЯ. Понимаются такие команды. ip netns add ИМЯ создаёт пространство с одним интерфейсом lo. ip link add ИМЯ type veth peer name ПИР создаёт оба конца в текущем пространстве; ip link add ИМЯ type ТИП без слова peer создаёт один интерфейс (bridge, dummy и т. д.). ip link set [dev] ИМЯ с одним или несколькими действиями подряд: up, down; netns ПРОСТР (переносит интерфейс в другое пространство; по правилу модели перенесённый интерфейс выключен, без адресов и без моста); name НОВОЕ (переименование: порты, подключённые к этому интерфейсу как к мосту, следуют за новым именем); master МОСТ (мост лежит в том же пространстве). ip addr add CIDR dev ИМЯ (или ip address add) дописывает CIDR в конец списка адресов. Всё остальное (ip route, ping, sysctl, ip -br addr и т. п.) игнорируйте. Каждый новый интерфейс, включая lo, выключен, без адресов и без моста. Пространство host существует всегда и вначале пусто. Скрипт корректен: всё, что он упоминает, уже создано. Напишите функцию netns_state(script): верните словарь пространство → интерфейс → {"up": bool, "addrs": [строки CIDR в порядке добавления], "master": имя моста или пустая строка}.', 'def netns_state(script):
    pass
', 'Сначала склейте строки с обратной косой чертой, потом разбирайте каждую по токенам: снимите sudo, определите пространство, затем смотрите на t[0] и t[1]. В link set пройдите по оставшимся словам циклом: у netns, name и master по два слова.', '{"func": "netns_state", "tests": [{"args": [""], "expected": {"host": {}}}, {"args": ["# only comments\n\n   \n# and blanks\n"], "expected": {"host": {}}}, {"args": ["sudo ip netns add red\nsudo ip netns add blue\nsudo ip link add br0 type bridge\nsudo ip addr add 10.200.0.1/24 dev br0\nsudo ip link set br0 up\nsudo ip link add vr type veth peer name vr-br\nsudo ip link set vr netns red\nsudo ip -n red link set vr name eth0\nsudo ip -n red addr add 10.200.0.2/24 dev eth0\nsudo ip -n red link set eth0 up\nsudo ip link set vr-br master br0\nsudo ip link set vr-br up\nsudo ip link add vb type veth peer name vb-br\nsudo ip link set vb netns blue\nsudo ip netns exec blue ip link set vb name eth0\nsudo ip netns exec blue ip addr add 10.200.0.3/24 dev eth0\nsudo ip netns exec blue ip link set eth0 up\nsudo ip link set vb-br master br0\nsudo ip link set vb-br up\n"], "expected": {"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/24"], "master": ""}}}}, {"args": ["sudo ip netns add a\nsudo ip link add x type veth peer name y\nsudo ip addr add 10.1.1.1/24 dev x\nsudo ip link set x up\nsudo ip link set x netns a\nsudo ip -n a addr add 10.1.1.2/24 dev x\nsudo ip link set y up\n"], "expected": {"host": {"y": {"up": true, "addrs": [], "master": ""}}, "a": {"lo": {"up": false, "addrs": [], "master": ""}, "x": {"up": false, "addrs": ["10.1.1.2/24"], "master": ""}}}}, {"args": ["ip netns add n1\nip link add br0 type bridge\nip link add p1 type veth peer name p2\nip link set p1 master br0\nip link set dev p1 up\nip link set dev br0 up\nip link set p1 down\nip addr add 192.0.2.1/24 dev br0\nip address add 2001:db8::1/64 dev br0\nip route add default via 192.0.2.254\nsysctl -w net.ipv4.ip_forward=1\nping -c1 192.0.2.254\n"], "expected": {"host": {"br0": {"up": true, "addrs": ["192.0.2.1/24", "2001:db8::1/64"], "master": ""}, "p1": {"up": false, "addrs": [], "master": "br0"}, "p2": {"up": false, "addrs": [], "master": ""}}, "n1": {"lo": {"up": false, "addrs": [], "master": ""}}}}, {"args": ["sudo ip netns add red\nsudo ip link add v1 type veth \\\n    peer name v1-br\nsudo ip link set v1 netns red\nsudo ip netns exec red ip link set v1 name eth0 \\\n  \nsudo ip netns exec red ip link set eth0 up\nsudo ip netns exec red ip link set lo up\nsudo ip netns exec red ip -br addr\nsudo ip netns exec red ping -c1 10.0.0.1\n"], "expected": {"host": {"v1-br": {"up": false, "addrs": [], "master": ""}}, "red": {"lo": {"up": true, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": [], "master": ""}}}}, {"args": ["sudo ip link add br0 type bridge\nsudo ip link add a type veth peer name b\nsudo ip link set a master br0 up\nsudo ip link set br0 name br1\n"], "expected": {"host": {"br1": {"up": false, "addrs": [], "master": ""}, "a": {"up": true, "addrs": [], "master": "br1"}, "b": {"up": false, "addrs": [], "master": ""}}}}, {"args": ["sudo ip link add dummy0 type dummy\nsudo ip addr add 10.9.9.9/32 dev dummy0\nsudo ip addr add 10.9.9.10/32 dev dummy0\nsudo ip link set dummy0 up\n"], "expected": {"host": {"dummy0": {"up": true, "addrs": ["10.9.9.9/32", "10.9.9.10/32"], "master": ""}}}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'la12-same-bridge-ping', 2, 'func', 'Дойдёт ли пинг по мосту', 'Модель сети на одном хосте. state — словарь пространство → интерфейс → {"up": bool, "addrs": [CIDR], "master": имя моста или ""}; pairs — список пар концов veth в виде ["ns/интерфейс", "ns/интерфейс"]. Маршрутов и пересылки в модели нет: пакет идёт только по уровню 2. Напишите функцию can_ping(state, pairs, src_ns, dst_ip): верните True, если ping на dst_ip из пространства src_ns успешен, иначе False. Правила. Интерфейс с непустым master — порт моста, адреса порта игнорируются, сам он пакетов не отправляет и не принимает. Если dst_ip принадлежит включённому интерфейсу (не порту) самого src_ns, ответ True. Иначе источником служит включённый интерфейс S пространства src_ns (не порт) с адресом A, чья сеть содержит dst_ip (маршрут «connected»). Кадр от S доходит до конца veth-пары: оба конца пары должны быть включены. Если конец-партнёр Q является портом моста M, то кадр попадает в мост: M должен быть включён, и дальше достижимы адреса самого моста M и концы-партнёры других портов M, у которых включён и порт, и его партнёр. Если Q не порт, достижим только сам Q. Если S сам мост (у него есть порты), достижимы концы-партнёры его включённых портов, у которых партнёр включён; сам S при этом тоже должен быть включён. Цель найдена, когда достижимый включённый интерфейс-не порт E имеет адрес ровно dst_ip и ещё адрес, чья сеть содержит адрес A источника (ответ должен вернуться). Если не нашлась ни одна пара S и E, верните False.', 'def can_ping(state, pairs, src_ns, dst_ip):
    pass
', 'Постройте словарь партнёров из pairs. Напишите вспомогательную функцию far_ends(ns, имя), которая возвращает список достижимых «ns/имя»; потом перебирайте источники и их адреса и сверяйте адреса концов через ipaddress.ip_interface.', '{"func": "can_ping", "tests": [{"args": [{"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "10.200.0.1"], "expected": true}, {"args": [{"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "10.200.0.3"], "expected": true}, {"args": [{"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "8.8.8.8"], "expected": false}, {"args": [{"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "host", "10.200.0.2"], "expected": true}, {"args": [{"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "10.200.0.2"], "expected": true}, {"args": [{"host": {"br0": {"up": false, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "10.200.0.1"], "expected": false}, {"args": [{"host": {"br0": {"up": false, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "10.200.0.3"], "expected": false}, {"args": [{"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": false, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "10.200.0.3"], "expected": false}, {"args": [{"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": false, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "10.200.0.1"], "expected": true}, {"args": [{"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": false, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "10.200.0.1"], "expected": false}, {"args": [{"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": ""}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "10.200.0.3"], "expected": false}, {"args": [{"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": ""}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "10.200.0.1"], "expected": false}, {"args": [{"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.201.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "10.201.0.3"], "expected": false}, {"args": [{"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/32"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "10.200.0.3"], "expected": false}, {"args": [{"host": {"br0": {"up": true, "addrs": ["10.200.0.1/24"], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": [], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "red", "10.200.0.1"], "expected": false}, {"args": [{"host": {"p0": {"up": true, "addrs": ["10.9.0.1/30"], "master": ""}}, "n": {"lo": {"up": false, "addrs": [], "master": ""}, "p1": {"up": true, "addrs": ["10.9.0.2/30"], "master": ""}}}, [["host/p0", "n/p1"]], "host", "10.9.0.2"], "expected": true}, {"args": [{"host": {"p0": {"up": true, "addrs": ["10.9.0.1/30"], "master": ""}}, "n": {"lo": {"up": false, "addrs": [], "master": ""}, "p1": {"up": true, "addrs": ["10.9.0.2/30"], "master": ""}}}, [["host/p0", "n/p1"]], "n", "10.9.0.1"], "expected": true}, {"args": [{"host": {"p0": {"up": true, "addrs": ["10.9.0.1/30"], "master": ""}}, "n": {"lo": {"up": false, "addrs": [], "master": ""}, "p1": {"up": true, "addrs": ["10.9.0.2/30"], "master": ""}}}, [["host/p0", "n/p1"]], "n", "10.9.0.3"], "expected": false}, {"args": [{"host": {"p0": {"up": true, "addrs": ["10.9.0.1/30"], "master": ""}}, "n": {"lo": {"up": false, "addrs": [], "master": ""}, "p1": {"up": false, "addrs": ["10.9.0.2/30"], "master": ""}}}, [["host/p0", "n/p1"]], "host", "10.9.0.2"], "expected": false}, {"args": [{"host": {"br0": {"up": true, "addrs": [], "master": ""}, "vr-br": {"up": true, "addrs": [], "master": "br0"}, "vb-br": {"up": true, "addrs": [], "master": "br0"}}, "red": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.2/24"], "master": ""}}, "blue": {"lo": {"up": false, "addrs": [], "master": ""}, "eth0": {"up": true, "addrs": ["10.200.0.3/24"], "master": ""}}}, [["red/eth0", "host/vr-br"], ["blue/eth0", "host/vb-br"]], "blue", "10.200.0.1"], "expected": false}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'la12-missing-step', 3, 'func', 'Какого шага не хватает', 'Из пространства не проходит ping во внешний мир. Даны выводы команд. addr_out — ip -br addr внутри пространства (колонки: имя, состояние, адреса; имя может быть вида eth0@if12); route_out — ip route внутри пространства; forward_out — одна строка sysctl net.ipv4.ip_forward на хосте, например net.ipv4.ip_forward = 0; nat_out — iptables -t nat -S POSTROUTING на хосте; gateway — адрес моста, который должен быть шлюзом; uplink — имя внешнего интерфейса хоста. Проверяйте по порядку и верните код первой найденной причины. link-down: нет интерфейса (кроме lo), у которого состояние ровно UP. no-address: у UP-интерфейсов нет IPv4-адреса; адресом пространства считается первый токен вида a.b.c.d/n первого такого интерфейса. no-default-route: в route_out нет строки, первое слово которой default. wrong-gateway: первая такая строка не содержит via и адрес gateway. ip-forward-off: значение после знака = (без пробелов по краям) не равно 1. no-masquerade: нет подходящего правила. Подходящее правило начинается с -A, имеет -j MASQUERADE или -j SNAT, а его условия не исключают пространство: если есть -s СЕТЬ (без ! перед ним), СЕТЬ должна содержать адрес пространства; если есть -o ИМЯ, то ИМЯ должно быть uplink; если есть ! -o ИМЯ, то ИМЯ не должно быть uplink. Правило без условий подходит. Если подходящее правило есть, верните ok.', 'def diagnose(addr_out, route_out, forward_out, nat_out, gateway, uplink):
    pass
', 'Идите по проверкам сверху вниз, как в списке. Для правил разберите строку по пробелам: индекс токена -s даёт сеть, токен перед -o подскажет, есть ли отрицание.', '{"func": "diagnose", "tests": [{"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 ! -o br0 -j MASQUERADE\n", "10.200.0.1", "enp1s0"], "expected": "ok"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        DOWN \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 ! -o br0 -j MASQUERADE\n", "10.200.0.1", "enp1s0"], "expected": "link-down"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 ! -o br0 -j MASQUERADE\n", "10.200.0.1", "enp1s0"], "expected": "link-down"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        LOWERLAYERDOWN 10.200.0.2/24 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 ! -o br0 -j MASQUERADE\n", "10.200.0.1", "enp1s0"], "expected": "link-down"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             fe80::c4a1:5eff:fe3b:1d22/64 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 ! -o br0 -j MASQUERADE\n", "10.200.0.1", "enp1s0"], "expected": "no-address"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 0\n", "-P PREROUTING ACCEPT\n-P INPUT ACCEPT\n-P OUTPUT ACCEPT\n-P POSTROUTING ACCEPT\n", "10.200.0.1", "enp1s0"], "expected": "no-default-route"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "default via 10.200.0.254 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 ! -o br0 -j MASQUERADE\n", "10.200.0.1", "enp1s0"], "expected": "wrong-gateway"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "default dev eth0 scope link \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 ! -o br0 -j MASQUERADE\n", "10.200.0.1", "enp1s0"], "expected": "wrong-gateway"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 0\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 ! -o br0 -j MASQUERADE\n", "10.200.0.1", "enp1s0"], "expected": "ip-forward-off"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 0\n", "-P PREROUTING ACCEPT\n-P INPUT ACCEPT\n-P OUTPUT ACCEPT\n-P POSTROUTING ACCEPT\n", "10.200.0.1", "enp1s0"], "expected": "ip-forward-off"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P PREROUTING ACCEPT\n-P INPUT ACCEPT\n-P OUTPUT ACCEPT\n-P POSTROUTING ACCEPT\n", "10.200.0.1", "enp1s0"], "expected": "no-masquerade"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 172.17.0.0/16 ! -o docker0 -j MASQUERADE\n", "10.200.0.1", "enp1s0"], "expected": "no-masquerade"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 -o wlan0 -j MASQUERADE\n", "10.200.0.1", "enp1s0"], "expected": "no-masquerade"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 -o enp1s0 -j SNAT --to-source 192.168.1.10\n", "10.200.0.1", "enp1s0"], "expected": "ok"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 -j LOG\n-A POSTROUTING -s 10.200.0.0/16 ! -o enp1s0 -j MASQUERADE\n", "10.200.0.1", "enp1s0"], "expected": "no-masquerade"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 ! -o enp1s0 -j MASQUERADE\n", "10.200.0.1", "enp1s0"], "expected": "no-masquerade"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 ! -o enp1s0 -j MASQUERADE\n", "10.200.0.1", "br0"], "expected": "ok"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if12        UP             10.200.0.2/24 fe80::c4a1:5eff:fe3b:1d22/64 \n", "default via 10.200.0.1 dev eth0 \n10.200.0.0/24 dev eth0 proto kernel scope link src 10.200.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -j MASQUERADE\n", "10.200.0.1", "enp1s0"], "expected": "ok"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if14        UP             10.201.0.2/24 \n", "default via 10.201.0.1 dev eth0 \n10.201.0.0/24 dev eth0 proto kernel scope link src 10.201.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 ! -o br0 -j MASQUERADE\n", "10.201.0.1", "enp1s0"], "expected": "no-masquerade"}, {"args": ["lo               UNKNOWN        127.0.0.1/8 ::1/128 \neth0@if14        UP             10.201.0.2/24 \n", "default via 10.201.0.1 dev eth0 \n10.201.0.0/24 dev eth0 proto kernel scope link src 10.201.0.2 \n", "net.ipv4.ip_forward = 1\n", "-P POSTROUTING ACCEPT\n-A POSTROUTING -s 10.200.0.0/24 ! -o br0 -j MASQUERADE\n-A POSTROUTING -s 10.201.0.0/24 ! -o br1 -j MASQUERADE\n", "10.201.0.1", "enp1s0"], "expected": "ok"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'la12-masq-ports', 4, 'func', 'Порты после маскарада', 'Несколько пространств выходят наружу через один хост, и маскарад подменяет адрес источника на host_ip. Две разные исходящие связи не могут иметь одинаковый набор (протокол, адрес и порт источника после подмены, адрес и порт назначения), иначе ядро не отличит их ответы. Модель: связи приходят по порядку и остаются открытыми. flows — список [proto, src_ip, sport, dst_ip, dport] (sport от 1024 до 65535). Напишите функцию masquerade(host_ip, flows): для каждой связи верните строку host_ip:порт. Правило выбора порта: если пара (proto, порт, dst_ip, dport) ещё не занята, порт остаётся прежним (sport). Иначе берётся первый свободный порт, считая вверх от sport + 1; после 65535 счёт продолжается с 1024. Связь с тем же полным исходным набором (proto, src_ip, sport, dst_ip, dport), что уже встречался, — это та же запись таблицы: она получает тот же ответ и ничего не занимает. Это упрощённая модель: настоящее ядро ищет свободный порт иначе, но принцип уникальности тот же.', 'def masquerade(host_ip, flows):
    pass
', 'Держите множество занятых (proto, порт, dst_ip, dport) и словарь уже виденных исходных наборов. Поиск свободного порта — цикл с переходом 65535 → 1024.', '{"func": "masquerade", "tests": [{"args": ["192.168.1.10", []], "expected": []}, {"args": ["192.168.1.10", [["tcp", "10.200.0.2", 45678, "203.0.113.9", 80]]], "expected": ["192.168.1.10:45678"]}, {"args": ["192.168.1.10", [["tcp", "10.200.0.2", 40000, "203.0.113.9", 80], ["tcp", "10.200.0.3", 40000, "203.0.113.9", 80], ["tcp", "10.200.0.4", 40000, "203.0.113.9", 80]]], "expected": ["192.168.1.10:40000", "192.168.1.10:40001", "192.168.1.10:40002"]}, {"args": ["192.168.1.10", [["tcp", "10.200.0.2", 40000, "203.0.113.9", 80], ["tcp", "10.200.0.3", 40000, "203.0.113.9", 443], ["tcp", "10.200.0.3", 40000, "198.51.100.5", 80]]], "expected": ["192.168.1.10:40000", "192.168.1.10:40000", "192.168.1.10:40000"]}, {"args": ["192.168.1.10", [["tcp", "10.200.0.2", 40000, "203.0.113.9", 53], ["udp", "10.200.0.3", 40000, "203.0.113.9", 53], ["udp", "10.200.0.4", 40000, "203.0.113.9", 53]]], "expected": ["192.168.1.10:40000", "192.168.1.10:40000", "192.168.1.10:40001"]}, {"args": ["192.168.1.10", [["tcp", "10.200.0.2", 40000, "203.0.113.9", 80], ["tcp", "10.200.0.2", 40000, "203.0.113.9", 80], ["tcp", "10.200.0.3", 40000, "203.0.113.9", 80], ["tcp", "10.200.0.2", 40000, "203.0.113.9", 80]]], "expected": ["192.168.1.10:40000", "192.168.1.10:40000", "192.168.1.10:40001", "192.168.1.10:40000"]}, {"args": ["198.51.100.1", [["tcp", "10.0.0.2", 65535, "203.0.113.9", 80], ["tcp", "10.0.0.3", 65535, "203.0.113.9", 80], ["tcp", "10.0.0.4", 65535, "203.0.113.9", 80], ["tcp", "10.0.0.5", 1024, "203.0.113.9", 80]]], "expected": ["198.51.100.1:65535", "198.51.100.1:1024", "198.51.100.1:1025", "198.51.100.1:1026"]}, {"args": ["198.51.100.1", [["tcp", "10.0.0.2", 1024, "203.0.113.9", 80], ["tcp", "10.0.0.3", 1025, "203.0.113.9", 80], ["tcp", "10.0.0.4", 1024, "203.0.113.9", 80], ["tcp", "10.0.0.5", 1024, "203.0.113.9", 80]]], "expected": ["198.51.100.1:1024", "198.51.100.1:1025", "198.51.100.1:1026", "198.51.100.1:1027"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'la12-published-port', 5, 'func', 'Куда попадёт пакет на опубликованный порт', 'rules — текст iptables-save для таблицы nat (строки *nat, :ЦЕПОЧКА, -A ЦЕПОЧКА условия -j ЦЕЛЬ, COMMIT и комментарии; нужны только строки -A). Пакет входит в цепочку PREROUTING и проходит правила сверху вниз. Правило сработало, если выполнены все его условия, из которых понимаются: -i ИМЯ и ! -i ИМЯ (входной интерфейс in_iface), -p ПРОТО и ! -p ПРОТО, --dport N или N:M (диапазон включительно; с ! — отрицание), -d АДРЕС[/МАСКА] и ! -d (адрес назначения dst_ip), -m addrtype --dst-type LOCAL (истинно, если dst_ip входит в local_ips). Остальные слова (-m tcp, -m udp и т. п.) игнорируйте. Правило без -j пропускайте. Цели: DNAT с --to-destination АДРЕС[:ПОРТ] — трансляция найдена, обход заканчивается; если порта нет, остаётся dport. ACCEPT — обход заканчивается без трансляции. RETURN — выход из текущей цепочки к вызвавшей (из PREROUTING — конец без трансляции). Имя цепочки, которая есть в rules, — переход в неё; если она закончилась или вернула управление, продолжаются правила вызывающей цепочки после перехода. Любая другая цель (LOG, MASQUERADE и т. д.) ничего не делает. Напишите функцию dnat_dest(rules, proto, dst_ip, dport, in_iface, local_ips): верните строку "адрес:порт" нового назначения или пустую строку, если пакет не транслируется.', 'def dnat_dest(rules, proto, dst_ip, dport, in_iface, local_ips):
    pass
', 'Соберите правила по цепочкам в словарь. Рекурсивная функция walk(цепочка) возвращает «dnat», «accept» или «return»; на переходе в пользовательскую цепочку продолжайте, только если вернулось «return».', '{"func": "dnat_dest", "tests": [{"args": ["# Generated by iptables-save v1.8.9 (nf_tables) on Mon Nov  3 10:00:00 2026\n*nat\n:PREROUTING ACCEPT [0:0]\n:INPUT ACCEPT [0:0]\n:OUTPUT ACCEPT [0:0]\n:POSTROUTING ACCEPT [0:0]\n:DOCKER - [0:0]\n-A PREROUTING -m addrtype --dst-type LOCAL -j DOCKER\n-A OUTPUT ! -d 127.0.0.0/8 -m addrtype --dst-type LOCAL -j DOCKER\n-A POSTROUTING -s 172.17.0.0/16 ! -o docker0 -j MASQUERADE\n-A DOCKER -i docker0 -j RETURN\n-A DOCKER ! -i docker0 -p tcp -m tcp --dport 8080 -j DNAT --to-destination 172.17.0.2:80\n-A DOCKER ! -i docker0 -p tcp -m tcp --dport 8443 -j DNAT --to-destination 172.17.0.3:443\n-A DOCKER ! -i docker0 -p udp -m udp --dport 5353 -j DNAT --to-destination 172.17.0.4:53\n-A DOCKER ! -i docker0 -p tcp -m tcp --dport 9000:9002 -j DNAT --to-destination 172.17.0.5\nCOMMIT\n# Completed on Mon Nov  3 10:00:00 2026\n", "tcp", "192.168.1.10", 8080, "enp1s0", ["192.168.1.10", "10.200.0.1", "127.0.0.1"]], "expected": "172.17.0.2:80"}, {"args": ["# Generated by iptables-save v1.8.9 (nf_tables) on Mon Nov  3 10:00:00 2026\n*nat\n:PREROUTING ACCEPT [0:0]\n:INPUT ACCEPT [0:0]\n:OUTPUT ACCEPT [0:0]\n:POSTROUTING ACCEPT [0:0]\n:DOCKER - [0:0]\n-A PREROUTING -m addrtype --dst-type LOCAL -j DOCKER\n-A OUTPUT ! -d 127.0.0.0/8 -m addrtype --dst-type LOCAL -j DOCKER\n-A POSTROUTING -s 172.17.0.0/16 ! -o docker0 -j MASQUERADE\n-A DOCKER -i docker0 -j RETURN\n-A DOCKER ! -i docker0 -p tcp -m tcp --dport 8080 -j DNAT --to-destination 172.17.0.2:80\n-A DOCKER ! -i docker0 -p tcp -m tcp --dport 8443 -j DNAT --to-destination 172.17.0.3:443\n-A DOCKER ! -i docker0 -p udp -m udp --dport 5353 -j DNAT --to-destination 172.17.0.4:53\n-A DOCKER ! -i docker0 -p tcp -m tcp --dport 9000:9002 -j DNAT --to-destination 172.17.0.5\nCOMMIT\n# Completed on Mon N