n 10.200.0.3:22\n-A POSTROUTING -s 10.200.0.0/24 ! -o br0 -j MASQUERADE\nCOMMIT\n", "tcp", "10.200.0.1", 8080, "br0", ["192.168.1.10", "10.200.0.1", "127.0.0.1"]], "expected": ""}, {"args": ["*nat\n:PREROUTING ACCEPT [0:0]\n:POSTROUTING ACCEPT [0:0]\n-A PREROUTING -d 192.168.1.10/32 -p tcp -m tcp --dport 8080 -j DNAT --to-destination 10.200.0.2:80\n-A PREROUTING -i br0 -p tcp -m tcp --dport 8080 -j ACCEPT\n-A PREROUTING -p tcp -m tcp --dport 2222 -j DNAT --to-destination 10.200.0.3:22\n-A POSTROUTING -s 10.200.0.0/24 ! -o br0 -j MASQUERADE\nCOMMIT\n", "tcp", "10.200.0.1", 2222, "br0", ["192.168.1.10", "10.200.0.1", "127.0.0.1"]], "expected": "10.200.0.3:22"}, {"args": ["*nat\n:PREROUTING ACCEPT [0:0]\n:POSTROUTING ACCEPT [0:0]\n-A PREROUTING -d 192.168.1.10/32 -p tcp -m tcp --dport 8080 -j DNAT --to-destination 10.200.0.2:80\n-A PREROUTING -i br0 -p tcp -m tcp --dport 8080 -j ACCEPT\n-A PREROUTING -p tcp -m tcp --dport 2222 -j DNAT --to-destination 10.200.0.3:22\n-A POSTROUTING -s 10.200.0.0/24 ! -o br0 -j MASQUERADE\nCOMMIT\n", "udp", "10.200.0.1", 2222, "br0", ["192.168.1.10", "10.200.0.1", "127.0.0.1"]], "expected": ""}, {"args": ["*nat\n:PREROUTING ACCEPT [0:0]\n:USERS - [0:0]\n-A PREROUTING -j USERS\n-A PREROUTING -p tcp -m tcp --dport 80 -j DNAT --to-destination 10.0.0.9:8080\n-A USERS -i wg0 -j ACCEPT\n-A USERS -p tcp -m tcp --dport 80 -j LOG\n-A USERS -p tcp -m tcp --dport 22 -j DNAT --to-destination 10.0.0.7\nCOMMIT\n", "tcp", "1.2.3.4", 80, "eth0", []], "expected": "10.0.0.9:8080"}, {"args": ["*nat\n:PREROUTING ACCEPT [0:0]\n:USERS - [0:0]\n-A PREROUTING -j USERS\n-A PREROUTING -p tcp -m tcp --dport 80 -j DNAT --to-destination 10.0.0.9:8080\n-A USERS -i wg0 -j ACCEPT\n-A USERS -p tcp -m tcp --dport 80 -j LOG\n-A USERS -p tcp -m tcp --dport 22 -j DNAT --to-destination 10.0.0.7\nCOMMIT\n", "tcp", "1.2.3.4", 80, "wg0", []], "expected": ""}, {"args": ["*nat\n:PREROUTING ACCEPT [0:0]\n:USERS - [0:0]\n-A PREROUTING -j USERS\n-A PREROUTING -p tcp -m tcp --dport 80 -j DNAT --to-destination 10.0.0.9:8080\n-A USERS -i wg0 -j ACCEPT\n-A USERS -p tcp -m tcp --dport 80 -j LOG\n-A USERS -p tcp -m tcp --dport 22 -j DNAT --to-destination 10.0.0.7\nCOMMIT\n", "tcp", "1.2.3.4", 22, "eth0", []], "expected": "10.0.0.7:22"}, {"args": ["*nat\n:PREROUTING ACCEPT [0:0]\n:USERS - [0:0]\n-A PREROUTING -j USERS\n-A PREROUTING -p tcp -m tcp --dport 80 -j DNAT --to-destination 10.0.0.9:8080\n-A USERS -i wg0 -j ACCEPT\n-A USERS -p tcp -m tcp --dport 80 -j LOG\n-A USERS -p tcp -m tcp --dport 22 -j DNAT --to-destination 10.0.0.7\nCOMMIT\n", "tcp", "1.2.3.4", 22, "wg0", []], "expected": ""}, {"args": ["*nat\n:PREROUTING ACCEPT [0:0]\nCOMMIT\n", "tcp", "1.2.3.4", 80, "eth0", []], "expected": ""}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'la12-conntrack-nat', 6, 'func', 'Что видно в conntrack', 'Вывод conntrack -L (или файл /proc/net/nf_conntrack): одна связь в строке, первое слово — протокол (tcp, udp, icmp). Если строка начинается со слов ipv4 или ipv6 и числа, их пропускайте: протокол — следующее слово. В строке два набора полей: первый (после первого src=) описывает пакет клиента, второй (после второго src=) — как придёт ответ. В наборе есть src, dst и, для tcp и udp, sport и dport. Остальные слова (состояние, [ASSURED], [UNREPLIED], packets=, bytes=, mark=, use=, type=, code=, id=) не нужны. Строки, где нет двух наборов (пустые, итоговая строка conntrack ... flow entries have been shown), пропускайте. Напишите функцию nat_entries(text): для каждой подходящей строки верните кортеж (proto, kind, client_seen_as, server_real). kind: snat, если dst ответного набора не равен src исходного или (при наличии портов) dport ответного не равен sport исходного; dnat, если src ответного не равен dst исходного или sport ответного не равен dport исходного; both, если верно и то и другое; none, если ничего. client_seen_as — dst:dport ответного набора (как внешний сервер видит клиента), server_real — src:sport ответного набора (кто на самом деле отвечает). Для строк без портов (icmp) оба значения — просто адрес.', 'def nat_entries(text):
    pass
', 'Разбейте строку на слова и пройдите по ним: слово, начинающееся с src=, открывает новый набор; dst, sport и dport кладите в последний открытый набор (первое вхождение каждого ключа).', '{"func": "nat_entries", "tests": [{"args": ["tcp      6 431982 ESTABLISHED src=10.200.0.2 dst=203.0.113.9 sport=45678 dport=80 src=203.0.113.9 dst=192.168.1.10 sport=80 dport=45678 [ASSURED] mark=0 use=1\nudp      17 28 src=10.200.0.3 dst=198.51.100.53 sport=41000 dport=53 src=198.51.100.53 dst=192.168.1.10 sport=53 dport=41000 mark=0 use=1\nicmp     1 29 src=10.200.0.2 dst=8.8.8.8 type=8 code=0 id=4321 src=8.8.8.8 dst=192.168.1.10 type=0 code=0 id=4321 mark=0 use=1\nconntrack v1.4.8 (conntrack-tools): 3 flow entries have been shown.\n"], "expected": [{"__tuple__": ["tcp", "snat", "192.168.1.10:45678", "203.0.113.9:80"]}, {"__tuple__": ["udp", "snat", "192.168.1.10:41000", "198.51.100.53:53"]}, {"__tuple__": ["icmp", "snat", "192.168.1.10", "8.8.8.8"]}]}, {"args": ["tcp      6 117 TIME_WAIT src=192.168.1.77 dst=192.168.1.10 sport=51000 dport=8080 src=10.200.0.2 dst=192.168.1.77 sport=80 dport=51000 [ASSURED] mark=0 use=1\ntcp      6 299 ESTABLISHED src=192.168.1.10 dst=192.168.1.10 sport=50000 dport=8080 src=10.200.0.2 dst=192.168.1.10 sport=80 dport=50000 [ASSURED] mark=0 use=1\nudp      17 25 src=10.200.0.2 dst=203.0.113.9 sport=5000 dport=53 [UNREPLIED] src=203.0.113.9 dst=10.200.0.2 sport=53 dport=5000 mark=0 use=1\n"], "expected": [{"__tuple__": ["tcp", "dnat", "192.168.1.77:51000", "10.200.0.2:80"]}, {"__tuple__": ["tcp", "dnat", "192.168.1.10:50000", "10.200.0.2:80"]}, {"__tuple__": ["udp", "none", "10.200.0.2:5000", "203.0.113.9:53"]}]}, {"args": ["ipv4     2 tcp      6 431999 ESTABLISHED src=10.200.0.2 dst=203.0.113.9 sport=33000 dport=443 packets=12 bytes=1500 src=203.0.113.9 dst=192.168.1.10 sport=443 dport=61222 packets=10 bytes=9100 [ASSURED] mark=0 zone=0 use=2\nipv4     2 udp      17 20 src=10.200.0.3 dst=224.0.0.251 sport=5353 dport=5353 [UNREPLIED] src=224.0.0.251 dst=10.200.0.3 sport=5353 dport=5353 mark=0 use=2\nipv4     2 tcp      6 60 SYN_SENT src=192.168.1.77 dst=192.168.1.10 sport=52000 dport=2222 [UNREPLIED] src=10.200.0.3 dst=192.168.1.77 sport=22 dport=52000 mark=0 use=1\n"], "expected": [{"__tuple__": ["tcp", "snat", "192.168.1.10:61222", "203.0.113.9:443"]}, {"__tuple__": ["udp", "none", "10.200.0.3:5353", "224.0.0.251:5353"]}, {"__tuple__": ["tcp", "dnat", "192.168.1.77:52000", "10.200.0.3:22"]}]}, {"args": ["tcp      6 10 CLOSE src=10.200.0.2 dst=192.168.1.10 sport=40000 dport=22 src=192.168.1.10 dst=10.200.0.2 sport=22 dport=40000 [ASSURED] mark=0 use=1\nicmp     1 5 src=192.168.1.77 dst=192.168.1.10 type=8 code=0 id=9 src=10.200.0.2 dst=192.168.1.77 type=0 code=0 id=9 mark=0 use=1\n"], "expected": [{"__tuple__": ["tcp", "none", "10.200.0.2:40000", "192.168.1.10:22"]}, {"__tuple__": ["icmp", "dnat", "192.168.1.77", "10.200.0.2"]}]}, {"args": [""], "expected": []}, {"args": ["conntrack v1.4.8 (conntrack-tools): 0 flow entries have been shown.\n"], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'la12-where-lost', 7, 'func', 'Где потерялся пакет', 'Администратор запустил ping на внешний адрес из пространства и одновременно снял tcpdump -n в нескольких точках пути: points — список [имя_точки, текст_вывода] в порядке от пространства наружу. В тексте есть служебные строки tcpdump и строки пакетов вида 10:15:01.123456 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 1, length 64 (перед IP может стоять заголовок канального уровня от ключа -e). Эхо-запрос — строка ICMP echo request, где адрес после > равен remote; ответ — строка ICMP echo reply, где адрес перед > равен remote; учитывайте только строки с id, равным icmp_id (адрес источника в запросе не сравнивайте: маскарад мог его заменить). Напишите функцию locate_drop(points, remote, icmp_id): верните одну из строк. no-request — запрос не виден в первой точке (или точек нет). request-lost-after:ИМЯ — запрос виден в первых k точках подряд, но в точке k+1 нет (ИМЯ — имя последней точки, где он виден; считайте по первому пропуску). Если запрос виден во всех точках: no-reply — ответ не виден в последней точке; reply-lost-after:ИМЯ — ответ виден в последней точке, но, двигаясь от последней точки к первой, он пропал: ИМЯ — имя последней точки по этому пути, где ответ ещё виден (первый пропуск при движении назад); ok — ответ виден везде.', 'def locate_drop(points, remote, icmp_id):
    pass
', 'Регулярное выражение IP (\S+) > (\S+): ICMP echo (request|reply), id (\d+), разберёт строку; для каждой точки получите два флага — виден запрос, виден ответ, — а потом применяйте правила по порядку.', '{"func": "locate_drop", "tests": [{"args": [[["red:eth0", "tcpdump: verbose output suppressed, use -v[v]... for full protocol decode\nlistening on eth0, link-type EN10MB (Ethernet), snapshot length 262144 bytes\n10:15:00.000001 IP 10.200.0.77 > 203.0.113.9: ICMP echo request, id 77, seq 1, length 64\n10:15:01.123456 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 1, length 64\n10:15:01.123456 IP 203.0.113.9 > 10.200.0.2: ICMP echo reply, id 4242, seq 1, length 64\n10:15:02.123463 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 2, length 64\n10:15:02.123463 IP 203.0.113.9 > 10.200.0.2: ICMP echo reply, id 4242, seq 2, length 64\n"], ["br0", "tcpdump: verbose output suppressed, use -v[v]... for full protocol decode\nlistening on br0, link-type EN10MB (Ethernet), snapshot length 262144 bytes\n10:15:00.000001 IP 10.200.0.77 > 203.0.113.9: ICMP echo request, id 77, seq 1, length 64\n10:15:01.123456 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 1, length 64\n10:15:01.123456 IP 203.0.113.9 > 10.200.0.2: ICMP echo reply, id 4242, seq 1, length 64\n10:15:02.123463 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 2, length 64\n10:15:02.123463 IP 203.0.113.9 > 10.200.0.2: ICMP echo reply, id 4242, seq 2, length 64\n"], ["enp1s0", "tcpdump: verbose output suppressed, use -v[v]... for full protocol decode\nlistening on enp1s0, link-type EN10MB (Ethernet), snapshot length 262144 bytes\n10:15:00.000001 IP 10.200.0.77 > 203.0.113.9: ICMP echo request, id 77, seq 1, length 64\n10:15:01.123456 IP 192.168.1.10 > 203.0.113.9: ICMP echo request, id 4242, seq 1, length 64\n10:15:01.123456 IP 203.0.113.9 > 192.168.1.10: ICMP echo reply, id 4242, seq 1, length 64\n10:15:02.123463 IP 192.168.1.10 > 203.0.113.9: ICMP echo request, id 4242, seq 2, length 64\n10:15:02.123463 IP 203.0.113.9 > 192.168.1.10: ICMP echo reply, id 4242, seq 2, length 64\n"]], "203.0.113.9", 4242], "expected": "ok"}, {"args": [[["red:eth0", "tcpdump: verbose output suppressed, use -v[v]... for full protocol decode\nlistening on eth0, link-type EN10MB (Ethernet), snapshot length 262144 bytes\n10:15:00.000001 IP 10.200.0.77 > 203.0.113.9: ICMP echo request, id 77, seq 1, length 64\n10:15:01.123456 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 1, length 64\n10:15:02.123463 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 2, length 64\n10:15:03.123470 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 3, length 64\n"], ["br0", "tcpdump: verbose output suppressed, use -v[v]... for full protocol decode\nlistening on br0, link-type EN10MB (Ethernet), snapshot length 262144 bytes\n10:15:00.000001 IP 10.200.0.77 > 203.0.113.9: ICMP echo request, id 77, seq 1, length 64\n10:15:01.123456 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 1, length 64\n10:15:02.123463 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 2, length 64\n10:15:03.123470 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 3, length 64\n"], ["enp1s0", "tcpdump: verbose output suppressed, use -v[v]... for full protocol decode\nlistening on enp1s0, link-type EN10MB (Ethernet), snapshot length 262144 bytes\n10:15:00.000001 IP 10.200.0.77 > 203.0.113.9: ICMP echo request, id 77, seq 1, length 64\n"]], "203.0.113.9", 4242], "expected": "request-lost-after:br0"}, {"args": [[["red:eth0", "tcpdump: verbose output suppressed, use -v[v]... for full protocol decode\nlistening on eth0, link-type EN10MB (Ethernet), snapshot length 262144 bytes\n10:15:00.000001 IP 10.200.0.77 > 203.0.113.9: ICMP echo request, id 77, seq 1, length 64\n10:15:01.123456 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 1, length 64\n10:15:02.123463 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 2, length 64\n"], ["br0", "tcpdump: verbose output suppressed, use -v[v]... for full protocol decode\nlistening on br0, link-type EN10MB (Ethernet), snapshot length 262144 bytes\n10:15:00.000001 IP 10.200.0.77 > 203.0.113.9: ICMP echo request, id 77, seq 1, length 64\n10:15:01.123456 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 1, length 64\n10:15:02.123463 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 2, length 64\n"], ["enp1s0", "tcpdump: verbose output suppressed, use -v[v]... for full protocol decode\nlistening on enp1s0, link-type EN10MB (Ethernet), snapshot length 262144 bytes\n10:15:00.000001 IP 10.200.0.77 > 203.0.113.9: ICMP echo request, id 77, seq 1, length 64\n10:15:01.123456 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 1, length 64\n10:15:02.123463 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 2, length 64\n"]], "203.0.113.9", 4242], "expected": "no-reply"}, {"args": [[["red:eth0", "tcpdump: verbose output suppressed, use -v[v]... for full protocol decode\nlistening on eth0, link-type EN10MB (Ethernet), snapshot length 262144 bytes\n10:15:00.000001 IP 10.200.0.77 > 203.0.113.9: ICMP echo request, id 77, seq 1, length 64\n10:15:01.123456 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 1, length 64\n10:15:02.123463 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 2, length 64\n"], ["br0", "tcpdump: verbose output suppressed, use -v[v]... for full protocol decode\nlistening on br0, link-type EN10MB (Ethernet), snapshot length 262144 bytes\n10:15:00.000001 IP 10.200.0.77 > 203.0.113.9: ICMP echo request, id 77, seq 1, length 64\n10:15:01.123456 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 1, length 64\n10:15:02.123463 IP 10.200.0.2 > 203.0.113.9: ICMP echo request, id 4242, seq 2, length 64\n"], ["enp1s0", "tcpdump: verbose output suppressed, use -v[v]... for full protocol decode\nlistening on enp1s0, link-type EN10MB (Ethernet), snapshot length 262144 bytes\n10:15: