INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'la12-veth-owner', 8, 'func', 'Чей это конец кабеля', 'Администратор смотрит на хосте список интерфейсов и хочет понять, в каком пространстве (контейнере) лежит другой конец каждого veth. Даны host_links — вывод ip -o link на хосте и ns_links — словарь имя пространства → вывод ip -o link внутри него. Строка начинается с индекса и имени: 25: veth3a2b1c0@if24: <BROADCAST,...; имя может иметь вид ИМЯ@ifN (N — индекс партнёра в другом пространстве) или ИМЯ@имя_партнёра (партнёр в том же пространстве) или просто ИМЯ. Индексы одинаковых чисел в разных пространствах не уникальны, поэтому сверяйте пару с двух сторон. Напишите функцию veth_owners(host_links, ns_links): для каждого интерфейса хоста вида ИМЯ@ifN верните в словаре ИМЯ → "пространство/интерфейс", где интерфейс внутри пространства имеет собственный индекс N и в его имени записано @ifM, M равно индексу интерфейса хоста. Если такого нет ни в одном пространстве, значение — пустая строка. Если подходящих несколько, берите пространство, первое по алфавиту. Интерфейсы хоста без @ifN (lo, eth0, мосты, партнёр в том же пространстве) в ответ не включайте.', 'def veth_owners(host_links, ns_links):
    pass
', 'Регулярное выражение ^(\d+):\s+([^:@\s]+)(?:@(\S+?))?: достаёт индекс, имя и необязательный партнёр из каждой строки. Для интерфейса хоста переберите пространства по алфавиту.', '{"func": "veth_owners", "tests": [{"args": ["1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n2: enp1s0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc fq_codel state UP mode DEFAULT group default qlen 1000\\    link/ether 52:54:00:12:34:56 brd ff:ff:ff:ff:ff:ff\n3: br0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\\    link/ether 4e:1a:2b:3c:4d:5e brd ff:ff:ff:ff:ff:ff\n8: vr-br@if7: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master br0 state UP mode DEFAULT group default qlen 1000\\    link/ether a2:11:22:33:44:55 brd ff:ff:ff:ff:ff:ff link-netns red\n10: vb-br@if9: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master br0 state UP mode DEFAULT group default qlen 1000\\    link/ether a2:66:77:88:99:aa brd ff:ff:ff:ff:ff:ff link-netns blue\n", {"red": "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n7: eth0@if8: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\\    link/ether 3e:11:22:33:44:55 brd ff:ff:ff:ff:ff:ff link-netnsid 0\n", "blue": "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n9: eth0@if10: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\\    link/ether 3e:66:77:88:99:aa brd ff:ff:ff:ff:ff:ff link-netnsid 0\n"}], "expected": {"vr-br": "red/eth0", "vb-br": "blue/eth0"}}, {"args": ["1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n2: enp1s0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc fq_codel state UP mode DEFAULT group default qlen 1000\\    link/ether 52:54:00:12:34:56 brd ff:ff:ff:ff:ff:ff\n3: br0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\\    link/ether 4e:1a:2b:3c:4d:5e brd ff:ff:ff:ff:ff:ff\n8: vr-br@if7: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master br0 state UP mode DEFAULT group default qlen 1000\\    link/ether a2:11:22:33:44:55 brd ff:ff:ff:ff:ff:ff link-netns red\n10: vb-br@if9: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master br0 state UP mode DEFAULT group default qlen 1000\\    link/ether a2:66:77:88:99:aa brd ff:ff:ff:ff:ff:ff link-netns blue\n", {"blue": "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n9: eth0@if10: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\\    link/ether 3e:66:77:88:99:aa brd ff:ff:ff:ff:ff:ff link-netnsid 0\n"}], "expected": {"vr-br": "", "vb-br": "blue/eth0"}}, {"args": ["1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n2: enp1s0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc fq_codel state UP mode DEFAULT group default qlen 1000\\    link/ether 52:54:00:12:34:56 brd ff:ff:ff:ff:ff:ff\n3: br0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\\    link/ether 4e:1a:2b:3c:4d:5e brd ff:ff:ff:ff:ff:ff\n8: vr-br@if7: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master br0 state UP mode DEFAULT group default qlen 1000\\    link/ether a2:11:22:33:44:55 brd ff:ff:ff:ff:ff:ff link-netns red\n10: vb-br@if9: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master br0 state UP mode DEFAULT group default qlen 1000\\    link/ether a2:66:77:88:99:aa brd ff:ff:ff:ff:ff:ff link-netns blue\n", {"red": "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n7: eth0@if99: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\\    link/ether 3e:aa:aa:aa:aa:aa brd ff:ff:ff:ff:ff:ff link-netnsid 0\n9: eth1@if3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\\    link/ether 3e:bb:bb:bb:bb:bb brd ff:ff:ff:ff:ff:ff link-netnsid 0\n", "blue": "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n9: eth0@if10: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\\    link/ether 3e:66:77:88:99:aa brd ff:ff:ff:ff:ff:ff link-netnsid 0\n"}], "expected": {"vr-br": "", "vb-br": "blue/eth0"}}, {"args": ["1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n2: eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc mq state UP mode DEFAULT group default qlen 1000\\    link/ether 02:42:c0:a8:01:0a brd ff:ff:ff:ff:ff:ff\n4: docker0: <NO-CARRIER,BROADCAST,MULTICAST,UP> mtu 1500 qdisc noqueue state DOWN mode DEFAULT group default\\    link/ether 02:42:aa:bb:cc:dd brd ff:ff:ff:ff:ff:ff\n25: veth3a2b1c0@if24: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default\\    link/ether 6e:aa:bb:cc:dd:01 brd ff:ff:ff:ff:ff:ff link-netnsid 0\n27: veth9f8e7d6@if26: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default\\    link/ether 6e:aa:bb:cc:dd:02 brd ff:ff:ff:ff:ff:ff link-netnsid 1\n29: veth0c0c0c0@vethpeer: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default\\    link/ether 6e:aa:bb:cc:dd:03 brd ff:ff:ff:ff:ff:ff\n31: veth-lost@if30: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default\\    link/ether 6e:aa:bb:cc:dd:04 brd ff:ff:ff:ff:ff:ff link-netnsid 2\n", {"web": "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n24: eth0@if25: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default\\    link/ether 02:42:ac:11:00:02 brd ff:ff:ff:ff:ff:ff link-netnsid 0\n", "db": "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n26: eth0@if27: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default\\    link/ether 02:42:ac:11:00:03 brd ff:ff:ff:ff:ff:ff link-netnsid 0\n"}], "expected": {"veth3a2b1c0": "web/eth0", "veth9f8e7d6": "db/eth0", "veth-lost": ""}}, {"args": ["1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n2: eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc mq state UP mode DEFAULT group default qlen 1000\\    link/ether 02:42:c0:a8:01:0a brd ff:ff:ff:ff:ff:ff\n4: docker0: <NO-CARRIER,BROADCAST,MULTICAST,UP> mtu 1500 qdisc noqueue state DOWN mode DEFAULT group default\\    link/ether 02:42:aa:bb:cc:dd brd ff:ff:ff:ff:ff:ff\n25: veth3a2b1c0@if24: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default\\    link/ether 6e:aa:bb:cc:dd:01 brd ff:ff:ff:ff:ff:ff link-netnsid 0\n27: veth9f8e7d6@if26: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default\\    link/ether 6e:aa:bb:cc:dd:02 brd ff:ff:ff:ff:ff:ff link-netnsid 1\n29: veth0c0c0c0@vethpeer: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default\\    link/ether 6e:aa:bb:cc:dd:03 brd ff:ff:ff:ff:ff:ff\n31: veth-lost@if30: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default\\    link/ether 6e:aa:bb:cc:dd:04 brd ff:ff:ff:ff:ff:ff link-netnsid 2\n", {"web": "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n24: eth0@if25: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default\\    link/ether 02:42:ac:11:00:02 brd ff:ff:ff:ff:ff:ff link-netnsid 0\n", "db": "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n26: eth0@if27: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default\\    link/ether 02:42:ac:11:00:03 brd ff:ff:ff:ff:ff:ff link-netnsid 0\n", "stray": "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n30: eth0@if999: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default\\    link/ether 02:42:ac:11:00:09 brd ff:ff:ff:ff:ff:ff link-netnsid 0\n"}], "expected": {"veth3a2b1c0": "web/eth0", "veth9f8e7d6": "db/eth0", "veth-lost": ""}}, {"args": ["1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n2: eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc mq state UP mode DEFAULT group default qlen 1000\\    link/ether 02:42:c0:a8:01:0a brd ff:ff:ff:ff:ff:ff\n4: docker0: <NO-CARRIER,BROADCAST,MULTICAST,UP> mtu 1500 qdisc noqueue state DOWN mode DEFAULT group default\\    link/ether 02:42:aa:bb:cc:dd brd ff:ff:ff:ff:ff:ff\n25: veth3a2b1c0@if24: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default\\    link/ether 6e:aa:bb:cc:dd:01 brd ff:ff:ff:ff:ff:ff link-netnsid 0\n27: veth9f8e7d6@if26: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default\\    link/ether 6e:aa:bb:cc:dd:02 brd ff:ff:ff:ff:ff:ff link-netnsid 1\n29: veth0c0c0c0@vethpeer: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default\\    link/ether 6e:aa:bb:cc:dd:03 brd ff:ff:ff:ff:ff:ff\n31: veth-lost@if30: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default\\    link/ether 6e:aa:bb:cc:dd:04 brd ff:ff:ff:ff:ff:ff link-netnsid 2\n", {}], "expected": {"veth3a2b1c0": "", "veth9f8e7d6": "", "veth-lost": ""}}, {"args": ["", {"red": "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000\\    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n7: eth0@if8: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\\    link/ether 3e:11:22:33:44:55 brd ff:ff:ff:ff:ff:ff link-netnsid 0\n"}], "expected": {}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'la12-subnet-pools', 9, 'func', 'Подсети из пулов, как у Docker', 'Менеджер сетей контейнеров выдаёт каждой новой сети подсеть из пулов адресов. pools — список [база, размер] в порядке приоритета, например ["172.17.0.0/16", 16] или ["192.168.0.0/16", 20]: из базы нарезаются подсети с длиной префикса размер. used — список CIDR, уже занятых на хосте (маршруты, существующие сети); они могут быть любого размера и не обязаны лежать на границах пула. Напишите функцию allocate_subnets(pools, used, count): верните список из count новых подсетей (строки CIDR) в порядке выдачи. Модель: пулы просматриваются по порядку; внутри пула кандидаты идут по возрастанию адреса; кандидат берётся, если не пересекается ни с одной занятой подсетью и ни с одной уже выданной в этом вызове. Пул, у которого размер меньше длины префикса базы или больше максимальной длины адреса, пропустите. Если кандидаты кончились раньше, верните сколько получилось. При count не больше нуля верните пустой список. Это модель: настоящий демон Docker делает похоже, но подробности зависят от версии.', 'def allocate_subnets(pools, used, count):
    pass
', 'ipaddress.ip_network(база).subnets(new_prefix=размер) отдаёт кандидатов по возрастанию; проверка пересечения — cand.overlaps(t). Выданные подсети тоже добавляйте в список занятых.', '{"func": "allocate_subnets", "tests": [{"args": [[["172.17.0.0/16", 16], ["172.18.0.0/16", 16], ["172.19.0.0/16", 16], ["172.20.0.0/14", 16], ["172.24.0.0/14", 16], ["172.28.0.0/14", 16], ["192.168.0.0/16", 20]], [], 1], "expected": ["172.17.0.0/16"]}, {"args": [[["172.17.0.0/16", 16], ["172.18.0.0/16", 16], ["172.19.0.0/16", 16], ["172.20.0.0/14", 16], ["172.24.0.0/14", 16], ["172.28.0.0/14", 16], ["192.168.0.0/16", 20]], ["172.17.0.0/16"], 3], "expected": ["172.18.0.0/16", "172.19.0.0/16", "172.20.0.0/16"]}, {"args": [[["172.17.0.0/16", 16], ["172.18.0.0/16", 16], ["172.19.0.0/16", 16], ["172.20.0.0/14", 16], ["172.24.0.0/14", 16], ["172.28.0.0/14", 16], ["192.168.0.0/16", 20]], ["172.17.0.0/16", "172.18.0.0/16", "172.19.0.0/16"], 2], "expected": ["172.20.0.0/16", "172.21.0.0/16"]}, {"args": [[["172.17.0.0/16", 16], ["172.18.0.0/16", 16], ["172.19.0.0/16", 16], ["172.20.0.0/14", 16], ["172.24.0.0/14", 16], ["172.28.0.0/14", 16], ["192.168.0.0/16", 20]], ["172.19.128.0/17"], 3], "expected": ["172.17.0.0/16", "172.18.0.0/16", "172.20.0.0/16"]}, {"args": [[["172.17.0.0/16", 16], ["172.18.0.0/16", 16], ["172.19.0.0/16", 16], ["172.20.0.0/14", 16], ["172.24.0.0/14", 16], ["172.28.0.0/14", 16], ["192.168.0.0/16", 20]], ["172.17.0.0/16", "172.18.0.0/16", "172.19.0.0/16", "172.20.5.0/24"], 2], "expected": ["172.21.0.0/16", "172.22.0.0/16"]}, {"args": [[["172.17.0.0/16", 16], ["172.18.0.0/16", 16], ["172.19.0.0/16", 16], ["172.20.0.0/14", 16], ["172.24.0.0/14", 16], ["172.28.0.0/14", 16], ["192.168.0.0/16", 20]], ["172.16.0.0/12"], 2], "expected": ["192.168.0.0/20", "192.168.16.0/20"]}, {"args": [[["172.17.0.0/16", 16], ["172.18.0.0/16", 16], ["172.19.0.0/16", 16], ["172.20.0.0/14", 16], ["172.24.0.0/14", 16], ["172.28.0.0/14", 16], ["192.168.0.0/16", 20]], ["172.16.0.0/11", "192.168.0.0/24"], 2], "expected": ["192.168.16.0/20", "192.168.32.0/20"]}, {"args": [[["10.10.0.0/16", 24]], ["10.10.0.0/24", "10.10.2.0/23"], 4], "expected": ["10.10.1.0/24", "10.10.4.0/24", "10.10.5.0/24", "10.10.6.0/24"]}, {"args": [[["10.10.0.0/24", 26]], [], 6], "expected": ["10.10.0.0/26", "10.10.0.64/26", "10.10.0.128/26", "10.10.0.192/26"]}, {"args": [[["10.0.0.0/24", 16], ["10.1.0.0/24", 25]], ["10.1.0.64/26"], 3], "expected": ["10.1.0.128/25"]}, {"args": [[["172.17.0.0/16", 16], ["172.18.0.0/16", 16], ["172.19.0.0/16", 16], ["172.20.0.0/14", 16], ["172.24.0.0/14", 16], ["172.28.0.0/14", 16], ["192.168.0.0/16", 20]], [], 0], "expected": []}, {"args": [[], [], 2], "expected": []}]}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'nb12-addresses', 10, 'func', 'Адреса интерфейсов на доске', 'Схема — словарь {"nodes": [...], "edges": [...]}. Узел: {"id": ..., "kind": ..., "name": ...}, у узла могут быть "params" — только явно заданные значения. kind — одно из netns, eth, veth, bridge, bond, vlan, vm, external, nat. У интерфейсов (eth, veth, bridge, bond, vlan, vm) бывают параметры net ("none" по умолчанию, "a", "b", "c" — три сети 10.0.1.0/24, 10.0.2.0/24, 10.0.3.0/24), up (true по умолчанию), access_vlan ("0" по умолчанию, "10", "20", "30"); у bond ещё mode ("active-backup" по умолчанию или "802.3ad"); у external параметр net по умолчанию "a". Связь {"from": id, "to": id}: netns → eth|veth|bridge|bond|vlan (интерфейс живёт в пространстве имён), veth ↔ veth (пара, достаточно одной связи в любую сторону), eth|veth|bond|vlan → bridge (порт моста), vm → bridge (tap), eth → bond (слейв), eth|bond → vlan (родитель), eth → external (кабель). Адрес интерфейса — 10.0.<сеть>.<номер>, где сеть: a → 1, b → 2, c → 3, а номер — позиция интерфейса среди всех интерфейсов доски с той же сетью (по порядку в списке nodes, с 1; порты моста и слейвы бонда тоже считаются). Интерфейсы без сети ("none") адреса не имеют. Узел external получает адрес 10.0.<сеть>.254. Напишите addresses(board) — словарь {id: адрес} для всех интерфейсов и узлов external, у которых есть адрес.', 'def addresses(board):
    pass
', 'Ведите счётчик отдельно для каждой сети и идите по nodes по порядку. У external номер не считается.', '{"func": "addresses", "tests": [{"args": [{"edges": [{"from": "host", "to": "v1h"}, {"from": "ns1", "to": "v1c"}, {"from": "v1h", "to": "v1c"}, {"from": "host", "to": "v2h"}, {"from": "ns2", "to": "v2c"}, {"from": "v2h", "to": "v2c"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "ns1", "kind": "netns", "name": "ns1"}, {"id": "ns2", "kind": "netns", "name": "ns2"}, {"id": "v1h", "kind": "veth", "name": "veth1-host"}, {"id": "v1c", "kind": "veth", "name": "veth1-ns1", "params": {"net": "a"}}, {"id": "v2h", "kind": "veth", "name": "veth2-host"}, {"id": "v2c", "kind": "veth", "name": "veth2-ns2", "params": {"net": "a"}}]}], "expected": {"v1c": "10.0.1.1", "v2c": "10.0.1.2"}}, {"args": [{"edges": [{"from": "host", "to": "br0"}, {"from": "vm1", "to": "br0"}, {"from": "vm2", "to": "br0"}, {"from": "vm3", "to": "br0"}, {"from": "vm4", "to": "br0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "br0", "kind": "bridge", "name": "br0"}, {"id": "vm1", "kind": "vm", "name": "vm1", "params": {"net": "a"}}, {"id": "vm2", "kind": "vm", "name": "vm2", "params": {"net": "a"}}, {"id": "vm3", "kind": "vm", "name": "vm3", "params": {"net": "a"}}, {"id": "vm4", "kind": "vm", "name": "vm4", "params": {"net": "a"}}]}], "expected": {"vm1": "10.0.1.1", "vm2": "10.0.1.2", "vm3": "10.0.1.3", "vm4": "10.0.1.4"}}, {"args": [{"edges": [{"from": "host", "to": "br0"}, {"from": "host", "to": "v1h"}, {"from": "ns1", "to": "v1c"}, {"from": "v1h", "to": "v1c"}, {"from": "v1h", "to": "br0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "ns1", "kind": "netns", "name": "ns1"}, {"id": "br0", "kind": "bridge", "name": "br0", "params": {"net": "a"}}, {"id": "v1h", "kind": "veth", "name": "veth1-host"}, {"id": "v1c", "kind": "veth", "name": "veth1-ns1", "params": {"net": "a", "up": false}}]}], "expected": {"br0": "10.0.1.1", "v1c": "10.0.1.2"}}, {"args": [{"edges": [{"from": "host", "to": "eth1"}, {"from": "eth1", "to": "sw"}, {"from": "host", "to": "eth2"}, {"from": "eth2", "to": "sw"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "sw", "kind": "external", "name": "switch"}, {"id": "eth1", "kind": "eth", "name": "eth1"}, {"id": "eth2", "kind": "eth", "name": "eth2"}]}], "expected": {"sw": "10.0.1.254"}}, {"args": [{"edges": [{"from": "host", "to": "eth1"}, {"from": "eth1", "to": "sw"}, {"from": "host", "to": "eth2"}, {"from": "eth2", "to": "sw"}, {"from": "host", "to": "bond0"}, {"from": "eth1", "to": "bond0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "sw", "kind": "external", "name": "switch"}, {"id": "eth1", "kind": "eth", "name": "eth1"}, {"id": "eth2", "kind": "eth", "name": "eth2"}, {"id": "bond0", "kind": "bond", "name": "bond0", "params": {"net": "a"}}]}], "expected": {"bond0": "10.0.1.1", "sw": "10.0.1.254"}}, {"args": [{"edges": [{"from": "host", "to": "eth1"}, {"from": "eth1", "to": "sw"}, {"from": "host", "to": "eth2"}, {"from": "eth2", "to": "sw"}, {"from": "host", "to": "bond0"}, {"from": "eth1", "to": "bond0"}, {"from": "eth2", "to": "bond0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "sw", "kind": "external", "name": "switch VLAN 20", "params": {"net": "b", "tagged": "20"}}, {"id": "eth1", "kind": "eth", "name": "eth1"}, {"id": "eth2", "kind": "eth", "name": "eth2"}, {"id": "bond0", "kind": "bond", "name": "bond0"}]}], "expected": {"sw": "10.0.2.254"}}, {"args": [{"edges": [{"from": "host", "to": "eth1"}, {"from": "eth1", "to": "sw1"}, {"from": "host", "to": "eth2"}, {"from": "eth2", "to": "sw2"}, {"from": "host", "to": "bond0"}, {"from": "eth1", "to": "bond0"}, {"from": "eth2", "to": "bond0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "sw1", "kind": "external", "name": "switch 1"}, {"id": "sw2", "kind": "external", "name": "switch 2"}, {"id": "eth1", "kind": "eth", "name": "eth1"}, {"id": "eth2", "kind": "eth", "name": "eth2"}, {"id": "bond0", "kind": "bond", "name": "bond0", "params": {"mode": "802.3ad", "net": "a"}}]}], "expected": {"bond0": "10.0.1.1", "sw1": "10.0.1.254", "sw2": "10.0.1.254"}}, {"args": [{"edges": [{"from": "host", "to": "eth1"}, {"from": "eth1", "to": "sw"}, {"from": "host", "to": "eth2"}, {"from": "eth2", "to": "sw"}, {"from": "host", "to": "bond0"}, {"from": "eth1", "to": "bond0"}, {"from": "eth2", "to": "bond0"}, {"from": "host", "to": "br0"}, {"from": "vm1", "to": "br0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "sw", "kind": "external", "name": "switch"}, {"id": "eth1", "kind": "eth", "name": "eth1"}, {"id": "eth2", "kind": "eth", "name": "eth2"}, {"id": "bond0", "kind": "bond", "name": "bond0"}, {"id": "br0", "kind": "bridge", "name": "br0", "params": {"up": false}}, {"id": "vm1", "kind": "vm", "name": "vm1", "params": {"net": "a"}}]}], "expected": {"sw": "10.0.1.254", "vm1": "10.0.1.1"}}, {"args": [{"edges": [{"from": "host", "to": "eth0"}, {"from": "eth0", "to": "net"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "ns1", "kind": "netns", "name": "ns1"}, {"id": "net", "kind": "external", "name": "internet"}, {"id": "eth0", "kind": "eth", "name": "eth0", "params": {"net": "a"}}]}], "expected": {"eth0": "10.0.1.1", "net": "10.0.1.254"}}], "board_view": true, "board_kind": "net_board"}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'nb12-link-states', 11, 'func', 'Состояние линков на доске', 'Схема — словарь {"nodes": [...], "edges": [...]}. Узел: {"id": ..., "kind": ..., "name": ...}, у узла могут быть "params" — только явно заданные значения. kind — одно из netns, eth, veth, bridge, bond, vlan, vm, external, nat. У интерфейсов (eth, veth, bridge, bond, vlan, vm) бывают параметры net ("none" по умолчанию, "a", "b", "c" — три сети 10.0.1.0/24, 10.0.2.0/24, 10.0.3.0/24), up (true по умолчанию), access_vlan ("0" по умолчанию, "10", "20", "30"); у bond ещё mode ("active-backup" по умолчанию или "802.3ad"); у external параметр net по умолчанию "a". Связь {"from": id, "to": id}: netns → eth|veth|bridge|bond|vlan (интерфейс живёт в пространстве имён), veth ↔ veth (пара, достаточно одной связи в любую сторону), eth|veth|bond|vlan → bridge (порт моста), vm → bridge (tap), eth → bond (слейв), eth|bond → vlan (родитель), eth → external (кабель). Состояние линка интерфейса (eth, veth, bridge, bond, vlan, vm) определяется по порядку: (1) интерфейс не vm и не живёт ни в одном пространстве имён (нет связи netns → интерфейс) — "no_carrier"; (2) параметр up равен false — "down"; (3) иначе по виду: eth — "up", если у него есть кабель (связь eth → external), иначе "no_carrier"; veth — "up", если у него есть пара, у пары up не false и пара живёт в пространстве имён, иначе "no_carrier"; bond — слейвы это eth со связью eth → bond; "up", если у хотя бы одного слейва состояние "up", иначе "no_carrier", а при mode "802.3ad" ещё "no_carrier", если живые слейвы подключены кабелями к разным external; vlan — "up", если "up" у родителя (связь eth|bond → vlan), иначе "no_carrier"; bridge — портами считаются интерфейсы со связью → bridge и vm со связью vm → bridge; "up", если есть порт с up не false и состоянием "up", иначе "no_carrier"; vm — "up", если у неё есть мост (связь vm → bridge) и у моста up не false, иначе "no_carrier". Напишите link_states(board) — словарь {id интерфейса: "up" | "down" | "no_carrier"}.', 'def link_states(board):
    pass
', 'Сделайте рекурсивную функцию state(узел): bond, vlan и bridge зависят от состояния других интерфейсов.', '{"func": "link_states", "tests": [{"args": [{"edges": [{"from": "host", "to": "v1h"}, {"from": "ns1", "to": "v1c"}, {"from": "v1h", "to": "v1c"}, {"from": "host", "to": "v2h"}, {"from": "ns2", "to": "v2c"}, {"from": "v2h", "to": "v2c"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "ns1", "kind": "netns", "name": "ns1"}, {"id": "ns2", "kind": "netns", "name": "ns2"}, {"id": "v1h", "kind": "veth", "name": "veth1-host"}, {"id": "v1c", "kind": "veth", "name": "veth1-ns1", "params": {"net": "a"}}, {"id": "v2h", "kind": "veth", "name": "veth2-host"}, {"id": "v2c", "kind": "veth", "name": "veth2-ns2", "params": {"net": "a"}}]}], "expected": {"v1c": "up", "v1h": "up", "v2c": "up", "v2h": "up"}}, {"args": [{"edges": [{"from": "host", "to": "br0"}, {"from": "vm1", "to": "br0"}, {"from": "vm2", "to": "br0"}, {"from": "vm3", "to": "br0"}, {"from": "vm4", "to": "br0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "br0", "kind": "bridge", "name": "br0"}, {"id": "vm1", "kind": "vm", "name": "vm1", "params": {"net": "a"}}, {"id": "vm2", "kind": "vm", "name": "vm2", "params": {"net": "a"}}, {"id": "vm3", "kind": "vm", "name": "vm3", "params": {"net": "a"}}, {"id": "vm4", "kind": "vm", "name": "vm4", "params": {"net": "a"}}]}], "expected": {"br0": "up", "vm1": "up", "vm2": "up", "vm3": "up", "vm4": "up"}}, {"args": [{"edges": [{"from": "host", "to": "br0"}, {"from": "host", "to": "br1"}, {"from": "vm1", "to": "br0"}, {"from": "vm2", "to": "br0"}, {"from": "vm3", "to": "br1"}, {"from": "vm4", "to": "br1"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "br0", "kind": "bridge", "name": "br0"}, {"id": "br1", "kind": "bridge", "name": "br1"}, {"id": "vm1", "kind": "vm", "name": "vm1", "params": {"net": "a"}}, {"id": "vm2", "kind": "vm", "name": "vm2", "params": {"net": "a"}}, {"id": "vm3", "kind": "vm", "name": "vm3", "params": {"net": "a"}}, {"id": "vm4", "kind": "vm", "name": "vm4", "params": {"net": "a"}}]}], "expected": {"br0": "up", "br1": "up", "vm1": "up", "vm2": "up", "vm3": "up", "vm4": "up"}}, {"args": [{"edges": [{"from": "host", "to": "br0"}, {"from": "host", "to": "v1h"}, {"from": "ns1", "to": "v1c"}, {"from": "v1h", "to": "v1c"}, {"from": "v1h", "to": "br0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "ns1", "kind": "netns", "name": "ns1"}, {"id": "br0", "kind": "bridge", "name": "br0", "params": {"net": "a"}}, {"id": "v1h", "kind": "veth", "name": "veth1-host"}, {"id": "v1c", "kind": "veth", "name": "veth1-ns1", "params": {"net": "a", "up": false}}]}], "expected": {"br0": "no_carrier", "v1c": "down", "v1h": "no_carrier"}}, {"args": [{"edges": [{"from": "host", "to": "eth1"}, {"from": "eth1", "to": "sw"}, {"from": "host", "to": "eth2"}, {"from": "eth2", "to": "sw"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "sw", "kind": "external", "name": "switch"}, {"id": "eth1", "kind": "eth", "name": "eth1"}, {"id": "eth2", "kind": "eth", "name": "eth2"}]}], "expected": {"eth1": "up", "eth2": "up"}}, {"args": [{"edges": [{"from": "host", "to": "eth1"}, {"from": "eth1", "to": "sw"}, {"from": "host", "to": "eth2"}, {"from": "eth2", "to": "sw"}, {"from": "host", "to": "bond0"}, {"from": "eth1", "to": "bond0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "sw", "kind": "external", "name": "switch"}, {"id": "eth1", "kind": "eth", "name": "eth1"}, {"id": "eth2", "kind": "eth", "name": "eth2"}, {"id": "bond0", "kind": "bond", "name": "bond0", "params": {"net": "a"}}]}], "expected": {"bond0": "up", "eth1": "up", "eth2": "up"}}, {"args": [{"edges": [{"from": "host", "to": "eth1"}, {"from": "eth1", "to": "sw"}, {"from": "host", "to": "eth2"}, {"from": "eth2", "to": "sw"}, {"from": "host", "to": "bond0"}, {"from": "eth1", "to": "bond0"}, {"from": "eth2", "to": "bond0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "sw", "kind": "external", "name": "switch"}, {"id": "eth1", "kind": "eth", "name": "eth1", "params": {"up": false}}, {"id": "eth2", "kind": "eth", "name": "eth2"}, {"id": "bond0", "kind": "bond", "name": "bond0", "params": {"net": "a"}}]}], "expected": {"bond0": "up", "eth1": "down", "eth2": "up"}}, {"args": [{"edges": [{"from": "host", "to": "eth1"}, {"from": "eth1", "to": "sw1"}, {"from": "host", "to": "eth2"}, {"from": "eth2", "to": "sw2"}, {"from": "host", "to": "bond0"}, {"from": "eth1", "to": "bond0"}, {"from": "eth2", "to": "bond0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "sw1", "kind": "external", "name": "switch 1"}, {"id": "sw2", "kind": "external", "name": "switch 2"}, {"id": "eth1", "kind": "eth", "name": "eth1"}, {"id": "eth2", "kind": "eth", "name": "eth2"}, {"id": "bond0", "kind": "bond", "name": "bond0", "params": {"mode": "802.3ad", "net": "a"}}]}], "expected": {"bond0": "no_carrier", "eth1": "up", "eth2": "up"}}, {"args": [{"edges": [{"from": "host", "to": "eth1"}, {"from": "eth1", "to": "sw"}, {"from": "host", "to": "eth2"}, {"from": "eth2", "to": "sw"}, {"from": "host", "to": "bond0"}, {"from": "eth1", "to": "bond0"}, {"from": "eth2", "to": "bond0"}, {"from": "host", "to": "br0"}, {"from": "vm1", "to": "br0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "sw", "kind": "external", "name": "switch"}, {"id": "eth1", "kind": "eth", "name": "eth1"}, {"id": "eth2", "kind": "eth", "name": "eth2"}, {"id": "bond0", "kind": "bond", "name": "bond0"}, {"id": "br0", "kind": "bridge", "name": "br0", "params": {"up": false}}, {"id": "vm1", "kind": "vm", "name": "vm1", "params": {"net": "a"}}]}], "expected": {"bond0": "up", "br0": "down", "eth1": "up", "eth2": "up", "vm1": "no_carrier"}}], "board_view": true, "board_kind": "net_board"}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'nb12-bridge-vlans', 12, 'func', 'VLAN-группы портов моста', 'Схема — словарь {"nodes": [...], "edges": [...]}. Узел: {"id": ..., "kind": ..., "name": ...}, у узла могут быть "params" — только явно заданные значения. kind — одно из netns, eth, veth, bridge, bond, vlan, vm, external, nat. У интерфейсов (eth, veth, bridge, bond, vlan, vm) бывают параметры net ("none" по умолчанию, "a", "b", "c" — три сети 10.0.1.0/24, 10.0.2.0/24, 10.0.3.0/24), up (true по умолчанию), access_vlan ("0" по умолчанию, "10", "20", "30"); у bond ещё mode ("active-backup" по умолчанию или "802.3ad"); у external параметр net по умолчанию "a". Связь {"from": id, "to": id}: netns → eth|veth|bridge|bond|vlan (интерфейс живёт в пространстве имён), veth ↔ veth (пара, достаточно одной связи в любую сторону), eth|veth|bond|vlan → bridge (порт моста), vm → bridge (tap), eth → bond (слейв), eth|bond → vlan (родитель), eth → external (кабель). Порт моста — eth, veth, bond или vlan со связью → bridge, а также vm со связью vm → bridge. У порта параметр access_vlan ("0" по умолчанию — без тега, "10", "20", "30"); порты одного моста с разными значениями друг с другом не общаются. Напишите bridge_vlans(board) — словарь {id моста: {тег: [id портов по возрастанию]}}; у моста без портов — {}.', 'def bridge_vlans(board):
    pass
', 'Для каждого моста пройдите по связям, ведущим в него, и сгруппируйте порты по access_vlan (строка).', '{"func": "bridge_vlans", "tests": [{"args": [{"edges": [{"from": "host", "to": "br0"}, {"from": "vm1", "to": "br0"}, {"from": "vm2", "to": "br0"}, {"from": "vm3", "to": "br0"}, {"from": "vm4", "to": "br0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "br0", "kind": "bridge", "name": "br0"}, {"id": "vm1", "kind": "vm", "name": "vm1", "params": {"net": "a"}}, {"id": "vm2", "kind": "vm", "name": "vm2", "params": {"net": "a"}}, {"id": "vm3", "kind": "vm", "name": "vm3", "params": {"net": "a"}}, {"id": "vm4", "kind": "vm", "name": "vm4", "params": {"net": "a"}}]}], "expected": {"br0": {"0": ["vm1", "vm2", "vm3", "vm4"]}}}, {"args": [{"edges": [{"from": "host", "to": "br0"}, {"from": "vm1", "to": "br0"}, {"from": "vm2", "to": "br0"}, {"from": "vm3", "to": "br0"}, {"from": "vm4", "to": "br0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "br0", "kind": "bridge", "name": "br0"}, {"id": "vm1", "kind": "vm", "name": "vm1", "params": {"access_vlan": "10", "net": "a"}}, {"id": "vm2", "kind": "vm", "name": "vm2", "params": {"access_vlan": "10", "net": "a"}}, {"id": "vm3", "kind": "vm", "name": "vm3", "params": {"access_vlan": "20", "net": "a"}}, {"id": "vm4", "kind": "vm", "name": "vm4", "params": {"access_vlan": "20", "net": "a"}}]}], "expected": {"br0": {"10": ["vm1", "vm2"], "20": ["vm3", "vm4"]}}}, {"args": [{"edges": [{"from": "host", "to": "br0"}, {"from": "host", "to": "br1"}, {"from": "vm1", "to": "br0"}, {"from": "vm2", "to": "br0"}, {"from": "vm3", "to": "br1"}, {"from": "vm4", "to": "br1"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "br0", "kind": "bridge", "name": "br0"}, {"id": "br1", "kind": "bridge", "name": "br1"}, {"id": "vm1", "kind": "vm", "name": "vm1", "params": {"net": "a"}}, {"id": "vm2", "kind": "vm", "name": "vm2", "params": {"net": "a"}}, {"id": "vm3", "kind": "vm", "name": "vm3", "params": {"net": "a"}}, {"id": "vm4", "kind": "vm", "name": "vm4", "params": {"net": "a"}}]}], "expected": {"br0": {"0": ["vm1", "vm2"]}, "br1": {"0": ["vm3", "vm4"]}}}, {"args": [{"edges": [{"from": "host", "to": "br0"}, {"from": "host", "to": "v1h"}, {"from": "ns1", "to": "v1c"}, {"from": "v1h", "to": "v1c"}, {"from": "v1h", "to": "br0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "ns1", "kind": "netns", "name": "ns1"}, {"id": "br0", "kind": "bridge", "name": "br0", "params": {"net": "a"}}, {"id": "v1h", "kind": "veth", "name": "veth1-host"}, {"id": "v1c", "kind": "veth", "name": "veth1-ns1", "params": {"net": "a", "up": false}}]}], "expected": {"br0": {"0": ["v1h"]}}}, {"args": [{"edges": [{"from": "host", "to": "eth1"}, {"from": "eth1", "to": "sw"}, {"from": "host", "to": "eth2"}, {"from": "eth2", "to": "sw"}, {"from": "host", "to": "bond0"}, {"from": "eth1", "to": "bond0"}, {"from": "eth2", "to": "bond0"}, {"from": "host", "to": "br0"}, {"from": "vm1", "to": "br0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "sw", "kind": "external", "name": "switch"}, {"id": "eth1", "kind": "eth", "name": "eth1"}, {"id": "eth2", "kind": "eth", "name": "eth2"}, {"id": "bond0", "kind": "bond", "name": "bond0"}, {"id": "br0", "kind": "bridge", "name": "br0", "params": {"up": false}}, {"id": "vm1", "kind": "vm", "name": "vm1", "params": {"net": "a"}}]}], "expected": {"br0": {"0": ["vm1"]}}}, {"args": [{"edges": [{"from": "host", "to": "eth0"}, {"from": "eth0", "to": "net"}, {"from": "masq", "to": "host"}], "nodes": [{"id": "host", "kind": "netns", "name": "host", "params": {"forward": true}}, {"id": "ns1", "kind": "netns", "name": "ns1"}, {"id": "net", "kind": "external", "name": "internet"}, {"id": "eth0", "kind": "eth", "name": "eth0", "params": {"net": "a"}}, {"id": "br0", "kind": "bridge", "name": "br0", "params": {"net": "b"}}, {"id": "v1h", "kind": "veth", "name": "veth1-host"}, {"id": "v1c", "kind": "veth", "name": "veth1-ns1", "params": {"default_route": true, "net": "b"}}, {"id": "masq", "kind": "nat", "name": "masquerade"}]}], "expected": {"br0": {}}}, {"args": [{"edges": [{"from": "host", "to": "v1h"}, {"from": "ns1", "to": "v1c"}, {"from": "v1h", "to": "v1c"}, {"from": "host", "to": "v2h"}, {"from": "ns2", "to": "v2c"}, {"from": "v2h", "to": "v2c"}, {"from": "host", "to": "br0"}, {"from": "v1h", "to": "br0"}, {"from": "v2h", "to": "br0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "ns1", "kind": "netns", "name": "ns1"}, {"id": "ns2", "kind": "netns", "name": "ns2"}, {"id": "v1h", "kind": "veth", "name": "veth1-host"}, {"id": "v1c", "kind": "veth", "name": "veth1-ns1", "params": {"net": "a"}}, {"id": "v2h", "kind": "veth", "name": "veth2-host"}, {"id": "v2c", "kind": "veth", "name": "veth2-ns2", "params": {"net": "a"}}, {"id": "br0", "kind": "bridge", "name": "br0"}]}], "expected": {"br0": {"0": ["v1h", "v2h"]}}}, {"args": [{"edges": [{"from": "host", "to": "v1h"}, {"from": "ns1", "to": "v1c"}, {"from": "v1h", "to": "v1c"}, {"from": "host", "to": "v2h"}, {"from": "ns2", "to": "v2c"}, {"from": "v2h", "to": "v2c"}, {"from": "host", "to": "br0"}, {"from": "v2h", "to": "br0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "ns1", "kind": "netns", "name": "ns1"}, {"id": "ns2", "kind": "netns", "name": "ns2"}, {"id": "v1h", "kind": "veth", "name": "veth1-host"}, {"id": "v1c", "kind": "veth", "name": "veth1-ns1", "params": {"net": "a"}}, {"id": "v2h", "kind": "veth", "name": "veth2-host"}, {"id": "v2c", "kind": "veth", "name": "veth2-ns2", "params": {"net": "a"}}, {"id": "br0", "kind": "bridge", "name": "br0"}]}], "expected": {"br0": {"0": ["v2h"]}}}, {"args": [{"edges": [{"from": "host", "to": "br0"}, {"from": "vm2", "to": "br0"}, {"from": "vm3", "to": "br0"}, {"from": "vm4", "to": "br0"}], "nodes": [{"id": "host", "kind": "netns", "name": "host"}, {"id": "br0", "kind": "bridge", "name": "br0"}, {"id": "vm1", "kind": "vm", "name": "vm1", "params": {"access_vlan": "10", "net": "a"}}, {"id": "vm2", "kind": "vm", "name": "vm2", "params": {"access_vlan": "10", "net": "a"}}, {"id": "vm3", "kind": "vm", "name": "vm3", "params": {"access_vlan": "20", "net": "a"}}, {"id": "vm4", "kind": "vm", "name": "vm4", "params": {"access_vlan": "20", "net": "a"}}]}], "expected": {"br0": {"10": ["vm2"], "20": ["vm3", "vm4"]}}}], "board_view": true, "board_kind": "net_board"}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 12, 'nb12-wire-network', 13, 'stdout', 'Соединить сеть контейнеров', 'Сеть собрана не до конца: объекты на месте, но некоторых связей не хватает. Схема — словарь {"nodes": [...], "edges": [...]}. Узел: {"id": ..., "kind": ..., "name": ...}, у узла могут быть "params" — только явно заданные значения. kind — одно из netns, eth, veth, bridge, bond, vlan, vm, external, nat. У интерфейсов (eth, veth, bridge, bond, vlan, vm) бывают параметры net ("none" по умолчанию, "a", "b", "c" — три сети 10.0.1.0/24, 10.0.2.0/24, 10.0.3.0/24), up (true по умолчанию), access_vlan ("0" по умолчанию, "10", "20", "30"); у bond ещё mode ("active-backup" по умолчанию или "802.3ad"); у external параметр net по умолчанию "a". Связь {"from": id, "to": id}: netns → eth|veth|bridge|bond|vlan (интерфейс живёт в пространстве имён), veth ↔ veth (пара, достаточно одной связи в любую сторону), eth|veth|bond|vlan → bridge (порт моста), vm → bridge (tap), eth → bond (слейв), eth|bond → vlan (родитель), eth → external (кабель). Концы veth называются <пара>-<имя пространства>, например veth1-host и veth1-ns1. Добавьте недостающие связи по правилам: (1) eth, bridge, bond и vlan живут в пространстве имён с именем "host" (netns → интерфейс); (2) veth-конец живёт в пространстве имён, имя которого стоит после дефиса в его имени; (3) два конца с одинаковой <парой> — пара (связь идёт от конца с суффиксом host к другому); (4) каждый veth-конец с суффиксом host — порт единственного моста доски; (5) каждый eth — слейв единственного бонда доски, если бонд есть; (6) каждый bond — порт единственного моста доски, и каждая vm — tap этого моста, если мост есть. Напишите fix(board) и верните {"add": [[from, to], ...], "remove": [[from, to], ...]} — какие связи добавить и какие убрать (объекты и параметры менять нельзя). Проверка запускает вашу функцию на четырёх разных досках (захардкодить ответ не выйдет), показывает каждую получившуюся доску со статусами и целями сценария, а решение принимается, когда на всех четырёх выполнены все цели.', 'def fix(board):
    # return {"add": [[from_id, to_id], ...], "remove": [[from_id, to_id], ...]}
    return {"add": [], "remove": []}
', 'Имя узла делится по первому дефису: <пара> и <пространство>. Проверяйте существующие связи по множеству пар (для veth — в обе стороны).', '{"driver": "import json as _json\nimport copy as _copy\n_BOARDS = _json.loads(r\"\"\"[{\"edges\":[{\"from\":\"host\",\"to\":\"v1h\"},{\"from\":\"ns1\",\"to\":\"v1c\"},{\"from\":\"v1h\",\"to\":\"v1c\"},{\"from\":\"host\",\"to\":\"br0\"},{\"from\":\"v1h\",\"to\":\"br0\"}],\"nodes\":[{\"id\":\"host\",\"kind\":\"netns\",\"name\":\"host\"},{\"id\":\"ns1\",\"kind\":\"netns\",\"name\":\"ns1\"},{\"id\":\"ns2\",\"kind\":\"netns\",\"name\":\"ns2\"},{\"id\":\"v1h\",\"kind\":\"veth\",\"name\":\"veth1-host\"},{\"id\":\"v1c\",\"kind\":\"veth\",\"name\":\"veth1-ns1\",\"params\":{\"net\":\"a\"}},{\"id\":\"v2h\",\"kind\":\"veth\",\"name\":\"veth2-host\"},{\"id\":\"v2c\",\"kind\":\"veth\",\"name\":\"veth2-ns2\",\"params\":{\"net\":\"a\"}},{\"id\":\"br0\",\"kind\":\"bridge\",\"name\":\"br0\"}]},{\"edges\":[{\"from\":\"host\",\"to\":\"eth0\"},{\"from\":\"eth0\",\"to\":\"net\"},{\"from\":\"masq\",\"to\":\"host\"}],\"nodes\":[{\"id\":\"host\",\"kind\":\"netns\",\"name\":\"host\",\"params\":{\"forward\":true}},{\"id\":\"ns1\",\"kind\":\"netns\",\"name\":\"ns1\"},{\"id\":\"net\",\"kind\":\"external\",\"name\":\"internet\"},{\"id\":\"eth0\",\"kind\":\"eth\",\"name\":\"eth0\",\"params\":{\"net\":\"a\"}},{\"id\":\"br0\",\"kind\":\"bridge\",\"name\":\"br0\",\"params\":{\"net\":\"b\"}},{\"id\":\"v1h\",\"kind\":\"veth\",\"name\":\"veth1-host\"},{\"id\":\"v1c\",\"kind\":\"veth\",\"name\":\"veth1-ns1\",\"params\":{\"default_route\":true,\"net\":\"b\"}},{\"id\":\"masq\",\"kind\":\"nat\",\"name\":\"masquerade\"}]},{\"edges\":[{\"from\":\"host\",\"to\":\"eth1\"},{\"from\":\"eth1\",\"to\":\"sw\"},{\"from\":\"eth2\",\"to\":\"sw\"},{\"from\":\"eth1\",\"to\":\"bond0\"}],\"nodes\":[{\"id\":\"host\",\"kind\":\"netns\",\"name\":\"host\"},{\"id\":\"sw\",\"kind\":\"external\",\"name\":\"switch\"},{\"id\":\"eth1\",\"kind\":\"eth\",\"name\":\"eth1\"},{\"id\":\"eth2\",\"kind\":\"eth\",\"name\":\"eth2\"},{\"id\":\"bond0\",\"kind\":\"bond\",\"name\":\"bond0\",\"params\":{\"net\":\"a\"}}]},{\"edges\":[{\"from\":\"host\",\"to\":\"eth1\"},{\"from\":\"eth1\",\"to\":\"sw\"},{\"from\":\"host\",\"to\":\"eth2\"},{\"from\":\"eth2\",\"to\":\"sw\"},{\"from\":\"host\",\"to\":\"bond0\"},{\"from\":\"eth2\",\"to\":\"bond0\"}],\"nodes\":[{\"id\":\"host\",\"kind\":\"netns\",\"name\":\"host\"},{\"id\":\"sw\",\"kind\":\"external\",\"name\":\"switch\"},{\"id\":\"eth1\",\"kind\":\"eth\",\"name\":\"eth1\"},{\"id\":\"eth2\",\"kind\":\"eth\",\"name\":\"eth2\"},{\"id\":\"bond0\",\"kind\":\"bond\",\"name\":\"bond0\"},{\"id\":\"br0\",\"kind\":\"bridge\",\"name\":\"br0\"},{\"id\":\"vm1\",\"kind\":\"vm\",\"name\":\"vm1\",\"params\":{\"net\":\"a\"}}]}]\"\"\")\n\ndef _after(board, answer):\n    if not isinstance(answer, dict):\n        raise TypeError(\"fix(board) must return a dict with the lists ''add'' and ''remove''\")\n    edges = [[e[\"from\"], e[\"to\"]] for e in board[\"edges\"]]\n    for pair in answer.get(\"remove\", []):\n        pair = list(pair)\n        if pair in edges:\n            edges.remove(pair)\n    for pair in answer.get(\"add\", []):\n        pair = list(pair)\n        if len(pair) != 2:\n            raise ValueError(\"a link is a pair [from, to]\")\n        if pair not in edges:\n            edges.append(pair)\n    return {\"nodes\": board[\"nodes\"], \"edges\": [{\"from\": a, \"to\": b} for a, b in edges]}\n\nfor _board in _BOARDS:\n    print(_json.dumps(_after(_board, fix(_copy.deepcopy(_board)))))\n", "expected": [], "board_check": [{"pack": "virt-fix-net", "scenario": "veth-pair"}, {"pack": "virt-fix-net", "scenario": "container"}, {"pack": "virt-fix-net", "scenario": "bond-slaves"}, {"pack": "virt-fix-net", "scenario": "vm-on-bond"}]}');
